// catalogue/gst-catalogue/build.gradle.kts — INV-T-2851 (T7), STK-61.
//
// The published `gst-catalogue` artefact: `ErrorCode`, with severity, disposition and
// owner (CS-13), generated by the `gst.catalogue-generator` plugin (catalogue/generator/)
// from catalogue/errors/error-codes.yaml. No hand-written domain logic lives here —
// only the generated enum, so consumers depend on `libs.gst.gstCatalogue` (TPL-01)
// exactly as CS-13/ARC-16 expect: an L3 vocabulary module, no framework, no other
// platform dependency.
//
// This module applies the Kotlin toolchain, detekt and Spotless/ktlint directly with
// the same versions platform-build/gradle/libs.versions.toml pins (STK-01, STK-67),
// rather than platform-build's own `gst.kotlin-base` convention plugin: consuming a
// plugin *published* from another repository's Maven registry needs that registry
// reachable for a *read* (pluginManagement resolution), which is a separate piece of
// infrastructure from the *write* path ci/publish.gitlab-ci.yml already has (GitLab's
// Token Access allowlist is documented there for cross-project *publish*, not consume).
// Pinning the same versions locally is the provisional default (AGT-04) until that
// read path exists; named here as a follow-up rather than left silent. The platform's
// own custom detekt/ktlint rule files (config/detekt/detekt.yml,
// config/ktlint/ktlint.editorconfig in platform-build) are not vendored here for the
// same reason — this module runs each tool's stock default configuration instead.

plugins {
    kotlin("jvm") version "2.4.20"
    id("dev.detekt") version "2.0.0-alpha.6"
    id("com.diffplug.spotless") version "8.10.3"
    id("gst.catalogue-generator")
    `maven-publish`
}

group = "com.dynokore.gst"
version = providers.gradleProperty("gstCatalogueVersion").get()

kotlin {
    jvmToolchain(25) // STK-01
    compilerOptions {
        allWarningsAsErrors.set(true) // CS-01
    }
}

detekt {
    buildUponDefaultConfig = true
}

spotless {
    kotlin {
        ktlint("1.8.0")
        targetExclude("**/build/**/*.kt")
    }
    kotlinGradle {
        ktlint("1.8.0")
        target("*.gradle.kts")
    }
}

dependencies {
    testImplementation(platform("org.junit:junit-bom:6.1.3"))
    testImplementation("org.junit.jupiter:junit-jupiter")
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

tasks.test {
    useJUnitPlatform()
    jvmArgs("-Duser.timezone=UTC")
    systemProperty("user.language", "de")
    systemProperty("user.country", "DE")
}

publishing {
    publications {
        create<MavenPublication>("maven") {
            from(components["java"])
        }
    }
    repositories {
        maven {
            // Same not-yet-reachable-by-default placeholder as build-logic/build.gradle.kts
            // and konsist-rules/build.gradle.kts in platform-build; ci/publish.gitlab-ci.yml's
            // `maven-publish` job overrides all three with the real GitLab package registry
            // URL/credentials of platform-build (project 225) when MAVEN_PUBLISH=true
            // (this repository's own .gitlab-ci.yml, coordinator note: no container
            // registry on this LAN GitLab — the Maven artefact via this publishing path
            // is what "published" means here).
            name = "gstMaven"
            url = uri(providers.gradleProperty("gstMavenUrl").getOrElse("https://repo.dynokore.internal/gst-maven"))
            credentials {
                username = providers.gradleProperty("gstMavenUser").orNull
                password = providers.gradleProperty("gstMavenPassword").orNull
            }
        }
    }
}
